SELECT kind || '~' || COALESCE(seller, '') || '~' || COALESCE(price, '') || '~' || COALESCE(r.room_short, '') || '~' || COALESCE(u.room_id, '') AS result FROM ( SELECT 'shop' AS kind, si.room_id AS room_id, si.sale_price AS price, si.item_name AS iname, '' AS seller FROM shop_items si UNION ALL SELECT 'npc' AS kind, n.room_id AS room_id, ni.sale_price AS price, ni.item_name AS iname, n.npc_name AS seller FROM npc_items ni JOIN npc_info n ON n.npc_id = ni.npc_id UNION ALL SELECT 'found' AS kind, '' AS room_id, i.special_find_note AS price, i.item_name AS iname, '' AS seller FROM items i WHERE i.special_find_note != '' ) AS u LEFT JOIN rooms r ON r.room_id = u.room_id WHERE u.iname LIKE '%cabbage%' AND u.price GLOB '*[0-9]*' AND u.room_id NOT IN (SELECT room_id FROM rooms WHERE room_short = 'Shonky Shop') ORDER BY result LIMIT 41;